/* Shared profile links open a focused storefront; app features ask for a brief sign-up. */
state.publicProfileMode=Object.hasOwn({lara:1,jose:1,watkins:1},new URL(location.href).searchParams.get('barber'));
function profileSignup(button){if(document.querySelector('#profile-signup-dialog'))return;const d=document.createElement('dialog');d.id='profile-signup-dialog';d.className='business-dialog profile-signup-dialog';d.innerHTML=`<button class="icon-btn profile-signup-close" data-close-profile-signup aria-label="Close">${icon('close')}</button><span class="profile-signup-eyebrow">YOUR NEXT GREAT LOOK STARTS HERE</span><h2>Make yourself<br>right at home.</h2><p>A quick introduction, then you can book, message your barber and keep your visits in one place.</p><form id="public-profile-signup"><label class="field">Your name<input name="name" autocomplete="name" maxlength="80" required></label><label class="field">Email<input name="email" type="email" autocomplete="email" maxlength="180" required></label><button class="btn full">Let’s get you in ${icon('arrow')}</button></form><p class="profile-signup-note">Your next great visit is just a few taps away.</p>`;document.body.append(d);d.showModal();d.addEventListener('cancel',()=>d.remove());d.querySelector('[data-close-profile-signup]').addEventListener('click',()=>{d.close();d.remove();});d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),email=String(f.get('email')).trim();if(!name||!email)return;extras.profile={...extras.profile,name,email};extras.customerSignedUp=true;save();d.close();d.remove();openProfileFeature(button);});}
function openProfileFeature(button){const attributes=[...button.attributes].filter(a=>a.name.startsWith('data-')),selector=attributes.map(a=>`[${a.name}="${CSS.escape(a.value)}"]`).join('');state.publicProfileMode=false;const url=new URL(location.href);url.searchParams.delete('barber');url.searchParams.delete('store');history.replaceState(null,'',url.pathname+url.search+url.hash);render();const target=selector?document.querySelector('button'+selector):null;if(target)target.click();}
window.addEventListener('click',e=>{if(!state.publicProfileMode)return;const b=e.target.closest('button');if(!b||b.closest('dialog')||b.matches('[data-profile-share],[data-profile-copy]'))return;const gated=b.closest('.bottom-nav,.side-nav,.customer-profile-actions,.customer-service-menu')||b.matches('[data-view],[data-action],[data-business],[data-x]');if(!gated)return;e.preventDefault();e.stopImmediatePropagation();if(extras.customerSignedUp)openProfileFeature(b);else profileSignup(b);},true);
const renderBeforePublicProfile=render;render=function(){renderBeforePublicProfile();document.body.dataset.publicProfile=state.publicProfileMode?'true':'false';if(!state.publicProfileMode)return;document.querySelectorAll('.bottom-nav .unread-badge').forEach(el=>el.remove());const b=B(),top=document.querySelector('.topbar');if(top)top.innerHTML=`<div class="public-store-brand"><span class="public-store-pole" aria-hidden="true"></span><strong>HAIRFLIX</strong><span>${esc(shops[extras.location].name)}</span></div><span class="public-profile-label">${esc(b.name)}’s chair</span>`;document.querySelectorAll('.page-head button,.page-head a').forEach(el=>{if(/all barbers/i.test(el.textContent))el.remove();});};
render();
